---- CREATION DES TABLES ----
/*
 * Fichier de l'équipe (rôle Données), avec UNE modification proposée par la
 * partie API (Leçon 9) : les clés primaires de GENRE, CONCEPTEUR, PLATEFORME et
 * JEU deviennent des colonnes identité « GENERATED BY DEFAULT ON NULL AS IDENTITY ».
 *   - Si l'API reçoit un identifiant NULL, la BD en assigne un, et la clause
 *     RETURNING ... INTO le retourne à Node.js (Leçon 9, diapos 21 à 23 : « si
 *     l'id est null la BD va l'assigner »; Leçon 7, diapos 25 à 27 : « Avec un id
 *     nul, c'est géré par la colonne de type identity »).
 *   - « BY DEFAULT ON NULL » plutôt que « ALWAYS » (Leçon 9, diapo 15) : comme le
 *     squelette d'insertion de la Leçon 9 (diapos 23 et 28), l'INSERT de l'API
 *     fournit la colonne identifiant, et la BD assigne une valeur seulement si
 *     elle est NULL.
 *   - Le tableau des besoins de transfert de l'analyse (« Ajouter un jeu » :
 *     titre, description, date_sortie, prix) ne fournit pas l'identifiant.
 * Les autres tables ne changent pas.
 */

CREATE TABLE concepteur (
    id_concepteur  INTEGER GENERATED BY DEFAULT ON NULL AS IDENTITY,
    nom_concepteur VARCHAR2(100) NOT NULL,
    pays           VARCHAR2(500)
);

ALTER TABLE concepteur ADD CONSTRAINT concepteur_pk PRIMARY KEY ( id_concepteur );

CREATE TABLE demande_vendeur (
    id_demande                 INTEGER NOT NULL,
    date_demande               DATE NOT NULL,
    statut                     VARCHAR2(20) NOT NULL,
    utilisateur_id_utilisateur INTEGER NOT NULL
);

ALTER TABLE demande_vendeur ADD CONSTRAINT demande_vendeur_pk PRIMARY KEY ( id_demande );

CREATE TABLE droit (
    id_droit    INTEGER NOT NULL,
    nom_droit   VARCHAR2(50) NOT NULL,
    description VARCHAR2(255)
);

ALTER TABLE droit ADD CONSTRAINT droit_pk PRIMARY KEY ( id_droit );

CREATE TABLE genre (
    id_genre    INTEGER GENERATED BY DEFAULT ON NULL AS IDENTITY,
    nom_genre   VARCHAR2(50) NOT NULL,
    description VARCHAR2(255)
);

ALTER TABLE genre ADD CONSTRAINT genre_pk PRIMARY KEY ( id_genre );

CREATE TABLE jeu (
    id_jeu                   INTEGER GENERATED BY DEFAULT ON NULL AS IDENTITY,
    titre                    VARCHAR2(100) NOT NULL,
    description              VARCHAR2(500),
    date_sortie              DATE,
    prix                     NUMBER NOT NULL,
    genre_id_genre           INTEGER NOT NULL,
    concepteur_id_concepteur INTEGER NOT NULL
);

ALTER TABLE jeu ADD CONSTRAINT jeu_pk PRIMARY KEY ( id_jeu );

CREATE TABLE jeu_plateforme (
    jeu_id_jeu               INTEGER NOT NULL,
    plateforme_id_plateforme INTEGER NOT NULL
);

ALTER TABLE jeu_plateforme ADD CONSTRAINT jeu_plateforme_pk PRIMARY KEY ( jeu_id_jeu,
                                                                          plateforme_id_plateforme );

CREATE TABLE plateforme (
    id_plateforme  INTEGER GENERATED BY DEFAULT ON NULL AS IDENTITY,
    nom_plateforme VARCHAR2(50) NOT NULL
);

ALTER TABLE plateforme ADD CONSTRAINT plateforme_pk PRIMARY KEY ( id_plateforme );

CREATE TABLE "SESSION" (
    id_session                 INTEGER NOT NULL,
    date_debut                 TIMESTAMP NOT NULL,
    date_fin                   TIMESTAMP,
    utilisateur_id_utilisateur INTEGER NOT NULL
);

ALTER TABLE "SESSION" ADD CONSTRAINT session_pk PRIMARY KEY ( id_session );

CREATE TABLE utilisateur (
    id_utilisateur INTEGER NOT NULL,
    nom            VARCHAR2(50) NOT NULL,
    prenom         VARCHAR2(50) NOT NULL,
    courriel       VARCHAR2(150) NOT NULL,
    mot_de_passe   VARCHAR2(255) NOT NULL,
    date_creation  DATE NOT NULL
);

ALTER TABLE utilisateur ADD CONSTRAINT utilisateur_pk PRIMARY KEY ( id_utilisateur );

CREATE TABLE utilisateur_droit (
    utilisateur_id_utilisateur INTEGER NOT NULL,
    droit_id_droit             INTEGER NOT NULL
);

ALTER TABLE utilisateur_droit ADD CONSTRAINT utilisateur_droit_pk PRIMARY KEY ( utilisateur_id_utilisateur,
                                                                                droit_id_droit );

ALTER TABLE demande_vendeur
    ADD CONSTRAINT demande_vendeur_utilisateur_fk FOREIGN KEY ( utilisateur_id_utilisateur )
        REFERENCES utilisateur ( id_utilisateur );

ALTER TABLE jeu
    ADD CONSTRAINT jeu_concepteur_fk FOREIGN KEY ( concepteur_id_concepteur )
        REFERENCES concepteur ( id_concepteur );

ALTER TABLE jeu
    ADD CONSTRAINT jeu_genre_fk FOREIGN KEY ( genre_id_genre )
        REFERENCES genre ( id_genre );

ALTER TABLE jeu_plateforme
    ADD CONSTRAINT jeu_plateforme_jeu_fk FOREIGN KEY ( jeu_id_jeu )
        REFERENCES jeu ( id_jeu );

ALTER TABLE jeu_plateforme
    ADD CONSTRAINT jeu_plateforme_plateforme_fk FOREIGN KEY ( plateforme_id_plateforme )
        REFERENCES plateforme ( id_plateforme );

ALTER TABLE "SESSION"
    ADD CONSTRAINT session_utilisateur_fk FOREIGN KEY ( utilisateur_id_utilisateur )
        REFERENCES utilisateur ( id_utilisateur );

ALTER TABLE utilisateur_droit
    ADD CONSTRAINT utilisateur_droit_droit_fk FOREIGN KEY ( droit_id_droit )
        REFERENCES droit ( id_droit );

ALTER TABLE utilisateur_droit
    ADD CONSTRAINT util_droit_util_fk FOREIGN KEY ( utilisateur_id_utilisateur )
        REFERENCES utilisateur ( id_utilisateur );
